/// <reference types="vitest" />
import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import * as path from 'path'
import { dbEditorPlugin } from './vite/dbEditorPlugin'

// https://vite.dev/config/
export default defineConfig({
  plugins: [react(), dbEditorPlugin({ writableRoot: 'storage/database' })],
  resolve: {
    alias: {
      '@': path.resolve(__dirname, './src'),
      '@public': path.resolve(__dirname, './public'),
      '@storage': path.resolve(__dirname, './storage'),
      '@titanui': path.resolve(__dirname, './src/ui/TitanUI')
    }
  },
  // воркер постройки патчей — ES-модуль (new Worker(..., { type: 'module' }))
  worker: { format: 'es' },
  test: {
    globals: true,
    environment: 'jsdom',
    setupFiles: ['./tests/setup.ts'],
    // Только тесты проекта: копии в worktree/scratch используют чужой корневой @ alias.
    include: ['tests/**/*.{test,spec}.{ts,tsx,js,jsx,mts,cts,mjs,cjs}'],
    exclude: ['**/node_modules/**', '**/dist/**', '**/.claude/**'],
    /**
     * `.env` не отслеживается git, поэтому значения оттуда у каждого свои, и
     * прогон, зависящий от них, воспроизводится по-разному на разных машинах.
     * Здесь закреплены все пять переменных, которые читает `src/config`:
     * `VITE_SHOW_STATS_PANEL` (панель статистики берёт 2D-контекст канваса,
     * которого в jsdom нет) и четыре остальных — `VITE_APP_NAME`,
     * `VITE_FS_DRIVER`, `VITE_FILE_BUCKET`, `VITE_S3_URL`. Последние сейчас ни
     * в одном тесте не проверяются, но `VITE_FS_DRIVER` читается в
     * `ResourceManager` при конструировании, то есть уже лежит на пути резолва.
     * Значения намеренно нерабочие: если тест начнёт зависеть от реального
     * хранилища, это станет видно сразу, а не превратится в тихий сетевой вызов.
     */
    env: {
      VITE_SHOW_STATS_PANEL: 'false',
      VITE_APP_NAME: 'Titan Engine (test)',
      VITE_FS_DRIVER: 'local',
      VITE_FILE_BUCKET: 'test-bucket',
      VITE_S3_URL: 'https://s3.invalid'
    }
  },
  server: {
    host: '127.0.0.1',
    port: 8085,
    strictPort: true
  }
})

sources.src/core/framework/generation/generateDa:
import { DatabaseSnapshot, validateDatabase, ScenarioRefs } from '@/core/framework/validation/validateDatabase'

/**
 * Генератор плоских файлов данных ("компилятор таблиц").
 *
 * Превращает снимок database обратно в TS-исходники — по файлу на таблицу
 * Значения запекаются как есть (числа уже вычислены в рантайме database)
 *
 * КОНТРАКТ ЭКСПОРТОВ: имена экспортируемых констант (Categories, Actors,
 * PhysicalObjects, ...) обязаны совпадать с тем, что импортирует
 * config/database.ts — иначе рантайм сломается. Эти имена зафиксированы ниже.
 */

/** Конфиг одной таблицы: имя экспорта, интерфейс, имя файла */
interface TableSpec<T> {
  /** имя экспортируемой константы (контракт с config/database.ts) */
  exportName: string
  /** имя TS-интерфейса для аннотации типа */
  interfaceName: string
  /** имя генерируемого файла (без расширения) */
  fileName: string
  /** строки данных */
  rows: T[]
}

export type GeneratorInput = DatabaseSnapshot

export interface GeneratedFile {
  path: string
  content: string
}

/**
 * Сериализует одно значение в TS-литерал.
 * Все значения в database — чистый JSON (числа, строки, null, массивы,
 * вложенные объекты), поэтому JSON.stringify корректен. Доводим до
 * стиля проекта (без кавычек у ключей-идентификаторов) ниже.
 */
function serializeValue(value: unknown): string {
  if (value === null) return 'null'
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) return 'null'

    return serializeNumber(value)
  }
  if (typeof value === 'string') return JSON.stringify(value)
  if (typeof value === 'boolean') return String(value)

  if (Array.isArray(value)) {
    return '[' + value.map(serializeValue).join(', ') + ']'
  }

  if (typeof value === 'object') {
    const entries = Object.entries(value as Record<string, unknown>)
      // отбрасываем undefined-поля (опциональные параметры ресурсов)
      .filter(([, v]) => v !== undefined)
      .map(([k, v]) => `${serializeKey(k)}: ${serializeValue(v)}`)

    return '{ ' + entries.join(', ') + ' }'
  }

  // функции/symbol/undefined в данных быть не должно — но не молчим
  throw new Error(`Cannot serialize value of type ${typeof value}: ${String(value)}`)
}

/** Ключ без кавычек, если это валидный идентификатор; иначе в кавычках */
function serializeKey(key: string): string {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(key) ? key : JSON.stringify(key)
}

function serializeRow(row: unknown): string {
  return '  ' + serializeValue(row)
}

function renderFile<T>(spec: TableSpec<T>): string {
  const header =
    `// ⚠️ AUTO-GENERATED FILE — DO NOT EDIT BY HAND.\n` +
    `// Generated from the database editor. Edit data via the editor UI, then regenerate.\n\n` +
    `import { ${spec.interfaceName} } from '@/core/models/types'\n\n`

  if (spec.rows.length === 0) {
    return header + `export const ${spec.exportName}: ${spec.interfaceName}[] = []\n`
  }

  const body = spec.rows.map(serializeRow).join(',\n')

  return header + `export const ${spec.exportName}: ${spec.interfaceName}[] = [\n${body}\n]\n`
}

/**
 * Главная функция. Прогоняет валидатор ПЕРЕД генерацией —
 * невалидные данные физически не могут быть записаны.
 *
 * @throws Error если данные не проходят валидацию (с перечислением ошибок)
 */
export function generateDatabaseFiles(
  input: GeneratorInput,
  scenarios: ScenarioRefs[] = [],
  options: { baseDir?: string; skipValidation?: boolean } = {}
): GeneratedFile[] {
  const baseDir = options.baseDir ?? 'storage/database'

  if (!options.skipValidation) {
    const validation = validateDatabase(input, scenarios)
    if (!validation.ok) {
      const list = validation.errors.map((e) => '  - ' + e.message).join('\n')
      throw new Error(`Refusing to generate: database has ${validation.errors.length} integrity error(s):\n${list}`)
    }
  }

  // Контракт экспортов фиксирован здесь. Менять имена нельзя без правки config/database.ts.
  const specs: TableSpec<unknown>[] = [
    { exportName: 'Categories', interfaceName: 'ICategory', fileName: 'categories', rows: input.categories },
    { exportName: 'Actors', interfaceName: 'IActor', fileName: 'actors', rows: input.actors },
    { exportName: 'Orbits', interfaceName: 'IOrbit', fileName: 'orbits', rows: input.orbits },
    {
      exportName: 'RotationObjects',
      interfaceName: 'IRotationObject',
      fileName: 'rotationObjects',
      rows: input.rotationObjects
    },
    {
      exportName: 'PhysicalObjects',
      interfaceName: 'IPhysicalObject',
      fileName: 'physicalObjects',
      rows: input.physicalObjects
    },
    {
      exportName: 'RenderingObjects',
      interfaceName: 'IRenderingObject',
      fileName: 'renderingObjects',
      rows: input.renderingObjects
    },
    { exportName: 'Placements', interfaceName: 'IPlacement', fileName: 'placements', rows: input.placements },
    { exportName: 'Resources', interfaceName: 'IResource', fileName: 'resources', rows: input.resources },
    {
      exportName: 'ActorResource',
      interfaceName: 'IActorResource',
      fileName: 'actorResource',
      rows: input.actorResource
    }
  ]

  const files: GeneratedFile[] = specs.map((spec) => ({
    path: `${baseDir}/${spec.fileName}.ts`,
    content: renderFile(spec)
  }))

  // index.ts реэкспортит все восемь массивов — это то, что импортирует config/database.ts
  files.push({
    path: `${baseDir}/index.ts`,
    content: renderIndex(specs)
  })

  return files
}

function renderIndex(specs: TableSpec<unknown>[]): string {
  const header = `// ⚠️ AUTO-GENERATED FILE — DO NOT EDIT BY HAND.\n\n`

  const reexports = specs.map((spec) => `export { ${spec.exportName} } from './${spec.fileName}'`).join('\n')

  return header + reexports + '\n'
}

function serializeNumber(value: number): string {
  const plain = String(value)

  // целые за пределами безопасного диапазона — обязательно в экспоненту
  if (Number.isInteger(value) && Math.abs(value) >= Number.MAX_SAFE_INTEGER) {
    return normalizeExponent(value.toExponential())
  }

  // в остальных случаях берём более короткую из двух записей
  const exp = normalizeExponent(value.toExponential())
  return exp.length < plain.length ? exp : plain
}

function normalizeExponent(exp: string): string {
  return exp.replace('e+', 'e')
}

sources.src/core/models/types.ts:
import type {
  ColorSpace,
  MagnificationTextureFilter,
  Mapping,
  MinificationTextureFilter,
  PixelFormat,
  TextureDataType,
  Wrapping
} from 'three'
import { AtmosphereConfig } from '@/core/renderables/Atmosphere/AtmosphereConfig'
import { NebulaRenderingData } from '@/core/renderables/Nebula/NebulaRenderingData'
import type { ProceduralSurfaceParams } from '@/core/terrain/proceduralSurfaceParams'
import type { BeltStructure } from '@/core/renderables/DetailedRingStreamingSystem/beltDensityProfile'

export type ValueOf<T> = T[keyof T]

export enum AllowedCategories {
  barycenter,
  blackHole,
  star,
  planet,
  atmosphere,
  ring,
  nebula,
  brownDwarf,
  whiteDwarf,
  giantStar,
  asteroidBelt,
  pulsar
}

export type AllowedCategory = keyof typeof AllowedCategories

export enum ResourceLifecycles {
  resident,
  streamable
}

export type ResourceLifecycle = keyof typeof ResourceLifecycles

export enum ResourceTypes {
  diffuse,
  cloud,
  night,
  // Маска «океан/суша» блика воды — читает только сфера (USE_SPECULAR); у рельефа блик даёт водная оболочка
  specular,
  cube,
  height,
  slope,
  detailDiffuse,
  detailNormal,
  detailArm,
  detailNormal2,
  // Normal-карта ряби воды (арка water-shader, Task 1) — тайлящийся сет,
  // трипланарный getNoiseWeighted сэмплирует её 3×4 раза (см. WaterShaderTemplate).
  // resident, wrapS+wrapT Repeat (спека Task 1) — как height/slope, не стрим.
  waterNormal
}

export type ResourceType = keyof typeof ResourceTypes

export type ResourceParameters = {
  mapping?: Mapping
  wrapS?: Wrapping
  wrapT?: Wrapping
  magFilter?: MagnificationTextureFilter
  minFilter?: MinificationTextureFilter
  format?: PixelFormat
  type?: TextureDataType
  anisotropy?: number
  colorSpace?: ColorSpace
}

export interface ICategory {
  readonly id: number
  readonly alias: AllowedCategory
  name: string
}

export interface IActor {
  readonly id: number
  readonly categoryId: number | AllowedCategory
  readonly parentId: number | null
  name: string
  description: string
  color: string
}

export interface IOrbit {
  readonly id: number
  readonly actorId: number
  semiMajorAxis: number
  eccentricity: number
  inclination: number
  argOfPeriapsis: number
  ascendingNode: number
  meanAnomalyAtEpoch: number
  /** Эпоха оскулирующих элементов — юлианская дата (сутки), на которую снята meanAnomalyAtEpoch */
  epoch: number
  /**
   * Явный сидерический период обращения, сутки; 0 = вывести из гравитационного
   * параметра. Обязателен для барицентрических подорбит (масса родителя-барицентра
   * не даёт корректного среднего движения)
   */
  period: number
}

export interface IRotationObject {
  readonly id: number
  readonly actorId: number
  meridianAngle: number
  ascendingNode: number
  inclination: number
  period: number
  direction?: 1 | -1
}

export interface IPhysicalObject {
  readonly id: number
  readonly actorId: number
  readonly parentId: number | null
  mass: number
  radius: number
  axialTilt: number
  rotationPeriod: number
  temperature: number
}

export interface IRenderingObject<T extends string = string, U = unknown> {
  readonly id: number
  readonly actorId: number
  data: Record<T, U>
}

/**
 * Статическая позиция актора — смещение от родителя в АСТРОНОМИЧЕСКИХ ЕДИНИЦАХ.
 *
 * Применима только к категориям с режимом позиционирования `placed`
 * (см. CATEGORY_RULES в validateDatabase). У акторов, чья позиция считается
 * по кеплеровой модели, строка здесь была бы ложью: DynamicNode перетирает
 * position на первом же кадре. Валидатор такую пару считает ошибкой.
 */
export interface IPlacement {
  readonly id: number
  readonly actorId: number
  x: number
  y: number
  z: number
  /** Точка Лагранжа орбиты родителя (L4 — впереди планеты, L5 — позади); координаты тогда не читаются */
  lagrange?: 4 | 5
}

export interface IResource extends ResourceParameters {
  readonly id: number
  readonly resourceType: ResourceType
  readonly lifecycle: ResourceLifecycle
  readonly path: string
  /** Предел кодировки уклона slope-карты (tan): байт 1/255 = ∓slopeRange, значения из SLOPE_RANGE_GRID. Только у resourceType "slope"; отсутствует — SLOPE_RANGE. */
  readonly slopeRange?: number
}

export interface IActorResource {
  readonly id: number
  readonly actorId: number
  readonly resourceId: number
}

/**
 * Ресурс, обогащённый привязкой к актору в точке сбора (actor.resources).
 * Сама таблица resources связана с акторами через пивот actorResource
 * (many-to-many), поэтому actorId у ресурса появляется только в контексте
 * конкретного актора — например, для группировки отложенных текстур.
 */
export interface IActorBoundResource extends IResource {
  readonly actorId?: number | null
}

export interface IPlanetRenderingObject {
