  /** Профиль облика камней: 'stony' | 'carbonaceous' | 'metallic' | 'icy' (дефолт 'stony') */
  profile?: string
  seed?: number
  /** Щели и сгущения радиального профиля (доли ширины) и дуги по азимуту (доли оборота); отсутствие — единица всюду */
  structure?: BeltStructure
  /** Включена ли пылевая дымка дальнего слоя (дефолт true) */
  dustEnabled?: boolean
  /** Цвет дымки: число 0xRRGGBB или строка '#rrggbb' */
  dustColor?: number | string
  /**
   * Оптическая толща дымки ПО ВЕРТИКАЛИ сквозь слой в средней плоскости
   * (дефолт 0.06: сверху лента непрозрачна на ~6%, в сгустках до ~14% —
   * едва заметна). У колец толща задаётся на просвет через ширину; у пояса
   * шириной в десятки а.е. такая калибровка делала бы дымку невидимой сверху.
   */
  dustTauVertical?: number
  /** Масштабная полутолщина пылевого слоя как доля полутолщины тора; не задана — 1/3 */
  dustScaleHeightFraction?: number
  /** Сила клочьев дымки 0..1: просветы до (1 − сила), сгустки до (1 + сила); 0 — ровная лента (дефолт 0.7) */
  dustClumpStrength?: number
  /** Масштаб клочьев дымки, а.е. (дефолт 0.6) */
  dustClumpScaleAu?: number
  /** Асимметрия фазовой функции Хеньи-Гринштейна дымки, 0..0.95: 0 — изотропно, больше — ярче на просвет к звезде (дефолт 0.55) */
  dustPhaseG?: number
  /** Сила фазового света 0..1: 0 — ровная яркость с любого угла, 1 — полная фазовая функция (дефолт 1) */
  dustPhaseStrength?: number
  /** Цвет дымки на просвет к звезде — смешивается с dustColor по силе прямого рассеяния (дефолт тёплый '#c8a98a') */
  dustColorForward?: number | string
  /**
   * Поглощение света за дымкой 0..1: доля оптической толщи τ вдоль луча, гасящая
   * звезду, её гало и фон (через них — блик и блум). 1 — честное пропускание e^−τ
   * (от середины пояса к звезде τ ≈ 12.7 — звезда гаснет), 0 — дымка только
   * добавляет свет, как прежде (дефолт 1).
   */
  dustExtinction?: number
  /** Художественный туман на камнях по дистанции (независим от dustTauVertical): км, на которых он набирает 63% в средней плоскости ленты; 0 — выключен (дефолт 40000) */
  rockFogRangeKm?: number
  /** Доля ледяных тел среди камней стримера, 0..1; 0 — все тела базового профиля (дефолт 0.15) */
  iceFraction?: number
  /** Профиль облика ледяных тел: имя из AsteroidProfiles (дефолт 'icy') */
  iceProfile?: string
  /** Средний период вращения камней, часы; 0 гасит вращение (дефолт 0) */
  spinPeriodHours?: number
  /** Число точек дальнего слоя, штук (дефолт 60000) */
  pointCount?: number
  /** Множитель размера точки дальнего слоя поверх физического (типичное тело крупнейшего класса на пиксель); дефолт 1 */
  pointScale?: number
  /** Запас отсечения секторов вокруг кадра — множитель fov камеры отсечения (см. AsteroidRingConfig.cullFovScale); дефолт 1.35 */
  cullFovScale?: number
  /** Длительность проявления сектора, секунды (см. AsteroidRingConfig.fadeSeconds); дефолт 0.8 */
  fadeSeconds?: number
}

export interface IBrownDwarfRenderingObject {
  seed?: number
  bandCount?: number
  turbulence?: number
  opticalDepth?: number
  gapGlow?: number
  limbDarkening?: number
  gapThreshold?: number
  deckSoftness?: number
  deckTint?: number
  parallax?: number
  breathAmplitude?: number
  bandWarp?: number
  zonalShear?: number
  fineDetail?: number
  polarChaos?: number
  vortexStrength?: number
  stormDepth?: number
}

/**
 * Пульсар: точка с гало (как белый карлик) и два луча-маяка. Углы в градусах,
 * длина в а.е.; период — секунды симуляционного времени (художественный, не
 * реальные миллисекунды).
 */
export interface IPulsarRenderingObject {
  /** Множитель яркости точки и гало (как у белого карлика) */
  exposureBias?: number
  /** Период оборота маяка, с (дефолт 4) */
  beamPeriodSeconds?: number
  /** Угол магнитной оси к оси вращения, ° (0 — луч вдоль оси, маяка нет) */
  beamTiltDeg?: number
  /** Полуугол конуса луча по уровню e⁻¹, ° */
  beamHalfAngleDeg?: number
  /** Длина луча, а.е.; за ней плотность 0 */
  beamLengthAu?: number
  beamColor?: number | string
  /** Яркость на оси у основания (HDR); 0 — лучей нет */
  beamIntensity?: number
  /** Фаза маяка на эпоху J2000, ° */
  beamPhaseDeg?: number
}

/**
 * Белый карлик. Ручек мало намеренно: поверхность безлика по физике (радиативная
 * атмосфера у горячих, гранула в 1/6000 радиуса у холодных), и рисовать на ней
 * нечего. Яркость и лимбовое потемнение выводятся из температуры физического
 * объекта, а не задаются здесь — см. WhiteDwarfParameters.
 */
export interface IWhiteDwarfRenderingObject {
  /**
   * Множитель поверх откалиброванного уровня яркости
   * (WHITE_DWARF_DISPLAY_SCALE). Единица — нейтральное значение.
   */
  exposureBias?: number
}

/**
 * Строка rendering звезды главной последовательности (категория 3) — по
 * желанию: без строки всё выводится из температуры физики.
 */
export interface IStarRenderingObject {
  /** Доля цвета звезды в прямом свете тел системы, [0, 1]; 0 — свет белый */
  lightTint?: number
  /** Конвективная активность 0..1 (грануляция и протуберанцы); не задана — по температуре. Лимб — всегда по температуре */
  activity?: number
}

/**
 * Звезда-гигант (красный гигант, сверхгигант, гипергигант — различие в данных).
 * Цвет, яркость и лимбовое потемнение выводятся из температуры физического
 * объекта — см. GiantStarParameters.
 */
export interface IGiantStarRenderingObject {
  seed?: number
  /** Масштаб домена ячеек: ячейка около R/3 при 5 */
  cellCount?: number
  /** Множитель температурного спреда ячеек */
  cellContrast?: number
  /** Полная протяжённость оболочки, доли радиуса */
  atmosphereHeight?: number
  /** Оптическая толща касательного луча; 0 гасит оболочку */
  atmosphereDensity?: number
  /** Множитель поверх откалиброванной яркости */
  exposureBias?: number
  /** Доля цвета звезды в прямом свете тел системы, [0, 1]; 0 — свет белый */
  lightTint?: number
}

export type Colorable = {
  r: number
  g: number
  b: number
}

export type TKeplerianModel = Omit<IOrbit, 'id' | 'actorId'>

export type TOrientationModel = Omit<IRotationObject, 'id' | 'actorId'>

