import { appendFileSync } from 'node:fs'

// Throwaway instrumentation: test bodies, assertions and timeouts stay intact.
// Use actual files, so aliases, fixture imports and UI behavior match the suite.
const phases: Plugin = {
  name: 'ui-compiler-phases', enforce: 'pre',
  transform(source, id) {
    if (id.includes('OptionalEnumExport') || id.includes('ResourceColorSpace')) appendFileSync('benchmark-results/ui-compiler-timeout-2026-10-23/transforms.log', id + '\n')
    const name = id.split('?')[0].replaceAll('\\', '/').split('/').at(-1)
    if (name !== 'OptionalEnumExport.spec.tsx' && name !== 'ResourceColorSpace.spec.tsx') return
    let code = "import { appendFileSync as recordCompilerPhase } from 'node:fs';\n" + source.replaceAll('\r\n', '\n')
    const replace = (from: string, to: string) => {
      if (!code.includes(from)) throw new Error(`Missing instrumentation marker: ${from}`)
      code = code.replace(from, to)
    }
    const log = (phase: string, expression: string, extra = '') => `recordCompilerPhase(process.env.UI_PHASE_REPORT!, JSON.stringify({ file: '${name}', phase: '${phase}', ms: performance.now() - (${expression})${extra} }) + '\\n');`
    if (name === 'OptionalEnumExport.spec.tsx') {
      replace('const db = await shippedSnapshot()', `const phaseFixtureStart = performance.now(); const db = await shippedSnapshot(); ${log('fixture', 'phaseFixtureStart')} const phaseUiStart = performance.now()`)
      replace('const files = generateDatabaseFiles', `${log('ui', 'phaseUiStart')} const files = generateDatabaseFiles`)
    } else {
      replace('const select = mount()\n  const unset', 'const phaseUiStart = performance.now(); const select = mount()\n  const unset')
      replace('expectCompilable(exported)', `${log('ui', 'phaseUiStart')} expectCompilable(exported)`)
    }
    replace('const program = ts.createProgram', 'const phaseProgramStart = performance.now(); const program = ts.createProgram')
    const afterProgram = `${log('createProgram', 'phaseProgramStart', ', files: program.getSourceFiles().length, bytes: program.getSourceFiles().reduce((n, f) => n + f.text.length, 0)')} const phaseDiagnosticsStart = performance.now();`
    if (name === 'OptionalEnumExport.spec.tsx') {
      replace('const diagnostics = ts.getPreEmitDiagnostics(program)', `${afterProgram} const diagnostics = ts.getPreEmitDiagnostics(program); ${log('diagnostics', 'phaseDiagnosticsStart')}`)
    } else {
      replace('expect(ts.getPreEmitDiagnostics(program).map', `${afterProgram} const diagnostics = ts.getPreEmitDiagnostics(program); ${log('diagnostics', 'phaseDiagnosticsStart')} expect(diagnostics.map`)
    }
    return { code, map: null }
  }
}
export default mergeConfig(base, defineConfig({ plugins: [phases] }))

